-- BÜCÜRÜKTOYS Viral 30 katalog veri güncellemesi.
-- Kaynak: lib/active-print-products.json + lib/viral-30-products.json
begin;

update public.print_products
set
  popularity_rank = null,
  is_featured = false,
  is_published = false,
  sort_order = 1000 + id,
  updated_at = now();

insert into public.print_products (
  id, sku, name, group_name, viral_strength, machine_fit, details,
  production_minutes_min, production_minutes_max, base_unit_price,
  min_order_quantity, material, image_key, description, standard_dimensions,
  approximate_weight, print_method, layer_height_mm, infill_percent, wall_count,
  nozzle_mm, supports, assembly, color_options, age_recommendation, usage_areas,
  packaging, license_note, market_signal, popularity_rank, quality_note,
  is_featured, is_published, sort_order
)
values
  (1,'3D-001','Articulated Flexi Dragon · Crystal Edition','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Kristal yüzeyli, tek parça basılan eklemli ejderha; ipek, gökkuşağı ve çift renk filamentle güçlü vitrin etkisi.',240,720,220,3,'PLA / Silk PLA','flexi','Crystal Dragon, hareketli gövdesi ve ışığı kıran kristal dokusuyla 3D baskı pazarının en kalıcı viral ürünlerinden biridir. Desteksiz ve baskıdan çıktığı anda hareketli olması seri üretimi kolaylaştırır; renk geçişli filamentlerde her parça benzersiz görünür.','Yaklaşık 18 × 6,5 × 4 cm','55–110 g','FDM · print-in-place (tek parça hareketli)',0.2,15,3,0.4,'Gerekmez; temiz ve iyi ayarlanmış tabla ilk katmanı gerekir.','Montaj yok; tabla sonrası eklem hareket kontrolü yapılır.','Tek renk, ipek, gökkuşağı, çift/üç renk ve kurumsal renk kombinasyonları','8+; küçük uçlar nedeniyle yetişkin gözetimi önerilir.','Oyuncak mağazası, koleksiyon, masaüstü ürün, hediye ve sosyal medya kampanyası','Şeffaf koruyucu poşet veya kutu; ürün kartı ve renk etiketi opsiyonel','Seçilen STL/modelin ticari üretim lisansı siparişten önce doğrulanır.','Flexi ejderhalar Etsy ve MakerWorld’de geniş ürün çeşitliliği ve sürekli görünürlük taşıyor.',1,'Eklem açıklığı, sivri uçlar, ilk katman ve renk geçişi numunede kontrol edilir.',true,true,1),
  (46,'3D-046','Dummy 13 Jointed Figure','Aksiyon figürleri, dönüşen oyuncaklar ve araçlar',5,'B','Tam pozlanabilir modüler aksiyon figürü; renk, zırh ve aksesuar kombinasyonlarıyla koleksiyon değeri yüksek.',360,900,340,1,'PETG iskelet + PLA zırh önerilir','action','Dummy 13, eklemli iç iskelet ve değiştirilebilir dış zırh parçalarından oluşan modüler bir aksiyon figürüdür. Pozlanabilirliği, yedek parça ve aksesuar ekosistemi sayesinde tek satıştan çok seri ve koleksiyon mantığıyla çalışır.','Standart boy yaklaşık 15 cm','70–120 g','FDM · çok parçalı modüler figür',0.16,20,4,0.4,'Doğru yönlendirmede çoğu parçada gerekmez; aksesuar modele göre değişir.','Tam montaj gerekir; eklemler kontrollü bastırma ile birleştirilir.','İskelet ve zırh ayrı renk; takım, karakter ve kurumsal tema kombinasyonları','14+ koleksiyon ürünü; çok sayıda küçük parça ve sıkı eklem içerir.','Koleksiyon, masaüstü pozlama, fotoğraf, boyama, aksesuar ve özel karakter serisi','Monte veya kit; parça listesi, montaj kartı ve kutu opsiyonları','Orijinal Dummy 13 lisansı ve seçilen remix/aksesuarın ticari kullanım şartları ayrı ayrı doğrulanır; atıf bilgisi ambalaja eklenir.','Dummy 13; resmi model sayfaları, remix ekosistemi ve özelleştirme seçenekleriyle güçlü koleksiyon ilgisi taşıyor.',2,'Eklem toleransı, PETG esnekliği, parça tamlığı ve 20 pozluk hareket testi yapılır.',true,true,2),
  (14,'3D-014','Articulated Flexi Octopus','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Sekiz hareketli kollu flexi ahtapot; farklı yüz ve renklerle geniş varyant üretimine uygun.',240,720,220,5,'PLA / Silk PLA','flexi','Flexi Ahtapot, tek gövdeden çıkan bağımsız hareketli kollarıyla dokunsal oyun ve masaüstü fidget ihtiyacını karşılar. Mini boydan vitrin boyuna ölçeklenebilir; komik yüz, çift renk ve tema varyantlarıyla tekrar siparişe uygundur.','Yaklaşık 12 × 12 × 3,5 cm','55–90 g','FDM · print-in-place eklemli',0.2,15,3,0.4,'Gerekmez.','Montaj yok; sekiz kolun hareketi ayrı ayrı kontrol edilir.','Tek renk, çift renk, ipek, gökkuşağı, deniz teması ve karışık paket','8+; küçük/mini varyantlar 3 yaş altına uygun değildir.','Fidget, oyuncak, masaüstü, deniz temalı etkinlik, hediye ve koleksiyon','Formu koruyan poşet veya kutu; tema etiketi opsiyonel','Ticari üretime izin veren ahtapot modeli seçilir.','Eklemli ahtapot ürünleri pazar yerlerinde binlerce değerlendirmeye ulaşan yerleşik bir 3D baskı kategorisi.',3,'Kol uçları, eklem boşlukları, yüz detayları ve taban yapışması numunede kontrol edilir.',true,true,3),
  (207,'3D-207','Fruit Turtle + Clicker','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','Meyve temalı sevimli kaplumbağa gövdesi ile tıklama mekanizmasını birleştiren fonksiyonel koleksiyon ürünü.',60,180,95,10,'PLA + clicker/switch mekanizması','fidget','Fruit Turtle + Clicker, çilek, limon, karpuz veya portakal temasını kaplumbağa karakteri ve dokunsal tıklama hissiyle birleştirir. Tek karakterden çok seri mantığıyla satılabilir; anahtarlık ve masaüstü varyantları tekrar siparişi destekler.','Yaklaşık 6,5 × 5 × 2,8 cm','30–45 g + mekanizma','FDM gövde + hazır tıklama mekanizması',0.16,15,3,0.4,'Modele göre gerekmez veya çok sınırlı kullanılır.','Clicker/switch takılır; kabuk ve gövde geçmesi kontrol edilir.','Çilek, limon, karpuz, portakal, üzüm ve özel marka rengi temaları','12+; sökülebilir mekanizma ve küçük parça içerebilir.','Fidget, anahtarlık, koleksiyon, hediye, kasa önü ve sosyal medya ürünü','Meyve adıyla tekli kartela veya koleksiyon kutusu; seri etiketi opsiyonel','Kaplumbağa modeli, meyve tasarımı ve clicker gövdesinin ticari lisansı doğrulanır.','Sevimli hayvan + clicker birleşimi, karakter koleksiyonu ve fonksiyonel fidget talebini aynı üründe topluyor.',4,'Mekanizma 20 tıklama, kabuk geçmesi, renk eşleşmesi ve anahtarlık gözü testinden geçirilir.',true,true,4),
  (87,'3D-087','Press-to-Spin / HelixCore Ball','Fidget, clicker, mekanik ve duyusal ürünler',4,'A','Basınca iç içe helisleri dönerek sıkışan kompakt top; tek elle kullanılabilen güçlü görsel ve dokunsal mekanizma.',60,150,95,10,'PLA / PETG','fidget','Press-to-Spin Helix Ball, eksen boyunca bastırıldığında iç içe geçen helis kanatlarının dönmesiyle çapını ve formunu değiştiren mekanik bir fidget ürünüdür. Hareketi tek bakışta anlaşılır, kısa videoda güçlü görünür ve farklı renk katmanlarıyla koleksiyon serisine dönüştürülebilir.','Kapalı hâlde yaklaşık Ø 6,5 cm','35–55 g','FDM · print-in-place veya geçmeli helis mekanizması',0.16,15,3,0.4,'Doğru yönlendirmede gerekmez.','Modele göre montajsızdır veya dış kabuk ile helis çekirdek pres geçmeyle birleştirilir.','Tek renk, çift renk, gökkuşağı, neon ve kurumsal renk katmanları','12+; hareketli aralıklarda parmak sıkıştırmamak için küçük çocuklarda gözetim gerekir.','Fidget, masaüstü, duyusal ürün, video içeriği, promosyon ve hediye','Tekli kartela veya kutu; basma yönünü gösteren kullanım piktogramı opsiyonel','HelixCore veya benzeri adla sunulan seçili modelin ticari üretim lisansı siparişten önce doğrulanır.','Basınca form değiştiren helis toplar, mekanizmayı tek hareketle anlatması ve videoda güçlü görünmesi sayesinde 2025–2026 fidget seçkilerinde öne çıkıyor.',5,'Her ürün 100 basma döngüsü, geri açılma, helis sürtünmesi ve katman ayrılması testinden geçirilir.',true,true,5),
  (82,'3D-082','Bolt Action / Clicker Fidget','Fidget, clicker, mekanik ve duyusal ürünler',4,'A','İleri–geri sürülen kolu belirgin klik hissi veren, gerçek silah formu taşımayan güvenli masaüstü mekanizması.',35,90,78,20,'PLA gövde + PETG sürgü','fidget','Bolt Action Clicker, kısa bir sürgü hareketini net ses ve dokunsal geri bildirimle birleştiren kompakt bir fidget ürünüdür. Katalog varyantı kalem ve masaüstü gadget formunda tasarlanır; gerçek silah parçası, namlu veya tetik içermez.','Yaklaşık 9 × 2,2 × 2 cm','20–34 g','FDM · çok parçalı sürgü ve klik mekanizması',0.16,20,4,0.4,'Gerekmez; parçalar tabla üzerinde ayrı basılır.','Sürgü gövdeye takılır; modele göre baskılı detent, küçük mıknatıs veya yay eklenir.','Yüksek görünürlüklü turuncu, mor, turkuaz, neon ve kurumsal renkler','14+; mıknatıs/yay kullanılan varyantlar küçük parça içerir.','Masaüstü fidget, anahtarlık, oyuncu hediyesi, kasa önü ve promosyon','Tekli güvenlik kartelası; mekanizma ve yaş uyarısı açıkça belirtilir','Yalnızca ticari lisanslı, soyut ve silah görünümü taşımayan gövde kullanılır; marka ve gerçek ekipman biçimi uygulanmaz.','Tek hareketli, sesli clicker mekanizmaları kısa video formatında hızlı anlaşılır ve düşük baskı süresiyle yüksek adetli satışa uygundur.',6,'Sürgü 100 çevrim, klik tutarlılığı, küçük parça tutuşu ve keskin kenar açısından kontrol edilir.',true,true,6),
  (96,'3D-096','Kişiselleştirilmiş İsim Anahtarlığı','Anahtarlık, çanta süsü, magnet ve küçük işlevsel hediyeler',5,'A','İsim, logo veya kısa kelimeyle kişiselleştirilen anahtarlık; düşük süre ve yüksek adet avantajı.',20,60,42,20,'PLA','custom','İsim Anahtarlığı, müşterinin adı, kısa mesajı veya marka kelimesiyle siparişe özel üretilir. Yazı tipi, zemin, iki renk ve bağlantı biçimi özelleştirilebilir; okul, etkinlik, düğün ve kurumsal promosyonlarda sürekli talep gören bir üründür.','Standart yaklaşık 7,5 × 2,5 × 0,5 cm; isme göre değişir','8–15 g + halka','FDM · parametrik/kişiselleştirilmiş model',0.16,20,3,0.4,'Gerekmez.','Anahtarlık halkası takılır; kişiselleştirme yazımı onay görseliyle kontrol edilir.','Zemin ve yazı ayrı renk; marka renkleri, neon, pastel ve karışık isim setleri','8+; metal halka ve küçük parça içerir.','Promosyon, okul, düğün/nişan, etkinlik, hediye, çanta etiketi ve personel seti','İsim bazında ayrılmış tekli poşet/kartela; toplu siparişte liste eşleştirmesi','Müşteri, gönderdiği isim/logo için kullanım hakkına sahip olmalıdır; yazı tipi lisansı doğrulanır.','Kişiselleştirilebilir isim anahtarlıkları MakerWorld’de çok sayıda parametrik tasarımla kalıcı talep kategorisi.',7,'Yazım, Türkçe karakter, iki renk hizası, halka deliği ve isim listesi yüzde 100 kontrol edilir.',false,true,7),
  (208,'3D-208','Expanding Iris Fidget','Fidget, clicker, mekanik ve duyusal ürünler',5,'B','Halkayı çevirince yaprakları açılıp kapanan mekanik iris; açık ve kapalı hâliyle güçlü vitrin ve video etkisi.',120,240,165,5,'PLA gövde + PETG pim/yaprak opsiyonu','fidget','Expanding Iris Fidget, üst üste kayan yaprakçıkların dış halkanın dönüşüyle merkezdeki açıklığı büyütüp küçülttüğü hassas bir mekanik oyuncaktır. Görsel dönüşümü sayesinde masaüstü ürünü, hediye ve premium promosyon olarak çalışır.','Yaklaşık Ø 10 × 1,8 cm','65–95 g','FDM · çok parçalı döner iris mekanizması',0.16,20,3,0.4,'Gerekmez; yaprakçıklar düz basılır.','Yaprakçıklar sıra ile pimlere yerleştirilir, ön ve arka halkalar kapatılıp dönüş ayarı yapılır.','Kontrast iki/üç renk, pastel, neon, metalik görünüm ve kurumsal renk','14+; çok parçalı mekanizma ve sıkışma aralıkları içerir.','Premium fidget, masaüstü obje, STEM gösterimi, hediye ve sosyal medya ürünü','Koruyucu kutu; açık/kapalı kullanım görseli ve mekanizma kartı opsiyonel','Kullanılacak iris mekanizmasının ticari lisansı ve varsa atıf şartı doğrulanır.','İris mekanizması, sonuç hareketinin kamerada güçlü görünmesi ve mekanik merak uyandırmasıyla yüksek paylaşılabilirlik taşır.',8,'Tam açma-kapama 50 çevrim, yaprak senkronu, sürtünme, pim tutuşu ve sıkışma aralığı test edilir.',false,true,8),
  (18,'3D-018','Flexi Yılan / Örümcek Serisi','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',4,'A','Uzun eklemli yılan ve sekiz hareketli bacaklı örümcek; renk geçişli filamentle çarpıcı flexi seri.',120,360,145,5,'PLA / Silk PLA','flexi','Flexi Yılan / Örümcek Serisi, uzun gövdeli kıvrılma hareketi ile çok bacaklı eklem yapısını aynı koleksiyonda buluşturur. Yılan standart ve büyük boy, örümcek ise masaüstü ve sezonluk varyantlarla sunulur; her ikisi de montajsız baskıya uygundur.','Yılan açık boy 45–60 cm; örümcek yaklaşık 9 × 9 × 3 cm','50–105 g','FDM · print-in-place eklemli',0.2,15,3,0.4,'Gerekmez.','Montaj yok; tüm gövde ve bacak eklemleri tabla sonrası tek tek açılır.','Gökkuşağı, çift renk, neon, fosforlu, doğal tonlar ve sezon temaları','8+; bacak uçları ve uzun eklem dizisi nedeniyle küçük çocuklarda gözetim önerilir.','Flexi oyuncak, fidget, masaüstü, hediye, Cadılar Bayramı ve vitrin serisi','Yılan kıvrık formda, örümcek bacak korumalı poşet/kutuda; seri etiketi opsiyonel','Yılan ve örümcek varyantlarının ticari üretim lisansları ayrı ayrı doğrulanır.','Uzun flexi hayvanlar, ejderhadan sonra renk geçişli filamentin hareketini en iyi gösteren kalıcı 3D baskı kategorilerindendir.',9,'Her eklem hareketi, ince bacak uçları, gövde kopma riski ve tabla yüzeyi yüzde 100 kontrol edilir.',false,true,9),
  (209,'3D-209','Retractable Işın Kılıcı Anahtarlık','Anahtarlık, çanta süsü, magnet ve küçük işlevsel hediyeler',5,'A','Teleskopik segmentleri çekilince uzayan, kapalı hâlde cep boy kalan renkli ışın kılıcı anahtarlık.',35,85,58,20,'PLA / PETG + metal halka','custom','Retractable Işın Kılıcı Anahtarlık, iç içe geçen ince segmentlerin merkezkaç veya elle çekme hareketiyle uzayıp tekrar kompakt gövdeye toplanmasıyla çalışan eğlenceli bir anahtarlıktır. Katalog ürünü özgün, markasız ve parlak oyuncak renklerinde hazırlanır.','Kapalı yaklaşık 8 cm; açık yaklaşık 28–32 cm','16–28 g + halka','FDM · iç içe teleskopik segmentler',0.16,15,3,0.4,'Gerekmez; ince segmentlerde iyi soğutma gerekir.','Teleskopik segmentler gövdeye sırayla takılır ve anahtarlık halkası monte edilir.','Turkuaz, mor, mercan, neon, fosforlu ve karışık gövde/ışın kombinasyonları','14+; ince teleskopik parçalar ve metal halka içerir.','Anahtarlık, çanta süsü, parti hediyesi, kasa önü, etkinlik ve video ürünü','Kapalı konumda tekli kartela; oyuncak ve yaş uyarısı görünür biçimde yazılır','Herhangi bir film, karakter, logo veya ticari evreni taklit etmeyen özgün ve ticari lisanslı model kullanılır.','Tek hareketle beklenmedik ölçüde uzayan cep boy ürünler, kısa video ve dürtüsel kasa önü satışı için güçlü bir gösteri etkisi taşır.',10,'Her segment 30 açma-kapama çevrimi, uç durdurucu, halka çekme ve keskin kenar açısından kontrol edilir.',false,true,10),
  (101,'3D-101','Mini Articulated Animal Keychain','Anahtarlık, çanta süsü, magnet ve küçük işlevsel hediyeler',5,'A','Kapibara, axolotl, kaplumbağa ve benzeri mini flexi hayvanlardan oluşan renkli anahtarlık koleksiyonu.',25,60,46,20,'PLA / Silk PLA + metal halka','custom','Mini Articulated Animal Keychain serisi, popüler sevimli hayvanları cep boy print-in-place gövdeler ve metal anahtarlık halkasıyla sunar. Düşük gramaj, çoklu tabla yerleşimi ve karakter çeşitliliği sayesinde toptan karışık paketler için idealdir.','Karaktere göre yaklaşık 4,5–6,5 cm','8–16 g + halka','FDM · print-in-place mini eklemli',0.16,15,3,0.4,'Gerekmez.','Anahtarlık halkası takılır; mini eklemler kontrollü biçimde açılır.','Karışık pastel, neon, ipek, gökkuşağı ve karaktere özel renk','8+; küçük parça ve metal halka içerir.','Anahtarlık, çanta süsü, parti hediyesi, okul etkinliği, promosyon ve kör paket','Tekli kartela, üçlü koleksiyon paketi veya karışık toptan kutu','Her karakter modelinin ticari kullanım hakkı ayrı doğrulanır; korunan karakterler kullanılmaz.','Mini eklemli hayvanlar, düşük giriş fiyatı ve koleksiyon tamamlatma davranışıyla 2026’da anahtarlık formatında güçlü büyüme gösteriyor.',11,'Halka gözü çekme, küçük eklem hareketi, karakter sayımı ve keskin çapak kontrolü yapılır.',false,true,11),
  (66,'3D-066','Infinity Cube','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','Sonsuz katlanma hareketi sunan kompakt fidget; sessiz masaüstü kullanımı ve toplu setler için uygun.',45,120,68,10,'PLA','fidget','Infinity Cube, sekiz küçük küpün sürekli içe ve dışa katlanmasıyla tekrar eden bir fidget hareketi sunar. Sessiz kullanımı ofis ve çalışma ortamına uygundur; doku, renk ve ağırlık seçenekleriyle farklı fiyat segmentleri oluşturulabilir.','Kapalı hâlde yaklaşık 4 × 4 × 4 cm','25–40 g','FDM · print-in-place veya pimli varyant',0.16,18,3,0.4,'Print-in-place varyantta gerekmez.','Modele göre montajsız veya sekiz küpün pimlerle birleştirilmesi gerekir.','Tek renk, iki renk, kontrast yüzey, kurumsal renk ve karışık paket','8+; sıkışma riskine karşı küçük çocuklarda gözetim önerilir.','Ofis, okul, duyusal ürün, promosyon, masaüstü ve hediye','Tekli poşet/kutu; kullanım hareketini gösteren mini kart opsiyonel','Seçilen mekanik modelin ticari kullanım hakkı doğrulanır.','Infinity Cube, ek parça gerektirmeyen ve herkesin anlayabildiği mekanizmasıyla kalıcı fidget kategorisinde.',12,'Tüm menteşeler 50 tam çevrimle, yüzeyler çapak ve sıkışma açısından kontrol edilir.',false,true,12),
  (210,'3D-210','Slide Action Fidget Keychain · Soyut Gövde','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','Yüksek görünürlüklü renklerde, namlu ve tetik içermeyen soyut gövdeli kayar mekanizmalı fidget anahtarlık.',45,100,75,20,'PLA gövde + PETG sürgü + metal halka','fidget','Slide Action Fidget Keychain, başparmakla ileri–geri kaydırılan sürgünün detent veya mıknatıs üzerinde net bir duruş hissi verdiği kompakt mekanik üründür. G26 aramasıyla bilinen ürün ailesinden ilham alsa da katalog varyantı gerçek silah ölçüsü, işlevi ve görünümü taşımayan soyut bir oyuncak gövde kullanır.','Yaklaşık 7 × 3,2 × 1,5 cm','18–30 g + halka','FDM · çok parçalı soyut sürgü mekanizması',0.16,20,4,0.4,'Gerekmez.','Sürgü, baskılı detent veya küçük mıknatısla gövdeye takılır; halka bağlantısı eklenir.','Turuncu, turkuaz, mor, mercan, neon ve kontrast iki renk','14+; mıknatıs ve metal halka içerebilir.','Fidget, anahtarlık, masaüstü gadget, oyuncu hediyesi ve promosyon','Oyuncak/fidget ibareli tekli kartela; güvenli kullanım ve yaş uyarısı eklenir','Marka, logo, gerçek silah geometrisi veya işlevsel parça kullanılmaz; yalnızca özgün ve ticari lisanslı soyut fidget tasarımı üretilir.','Kısa kaydırma ve net klik hissi sunan kompakt slider ürünler, ses ve hareketi videoda kolay aktardığı için yüksek etkileşim alıyor.',13,'Sürgü 100 çevrim, mıknatıs/pim tutuşu, halka çekme ve oyuncak formunun açıkça ayırt edilebilirliği kontrol edilir.',false,true,13),
  (125,'3D-125','Geometric Mini Planter','Ev dekoru, saksı, vazo ve masaüstü düzenleyiciler',5,'A','Low-poly yüzeyli kompakt saksı; sukulent, masaüstü hediye ve kurumsal renk serileri için güçlü dekor ürünü.',120,300,155,5,'PLA / PETG','decor','Geometric Mini Planter, düşük poligonlu yüzeylerin ışık ve gölgeyle oluşturduğu modern görünümü küçük bitki formatıyla birleştirir. Drenajlı veya iç hazneli üretilebilir; renk, yüzey ve logo etiketiyle mağaza ya da kurumsal hediye serisine uyarlanabilir.','Yaklaşık Ø 9 × 8,5 cm','80–140 g','FDM · çok duvarlı veya vase-mode varyant',0.2,8,4,0.4,'Gerekmez.','Montaj yok; isteğe göre iç hazne ve altlık ayrı eklenir.','Mat toprak tonları, pastel, terrazzo görünümü, taş dokusu ve kurumsal renk','Dekoratif ürün; oyuncak değildir.','Sukulent saksısı, masaüstü dekor, ofis hediyesi, mağaza vitrini ve kurumsal set','Çizilmeyi önleyen kâğıt dolgu ve kutu; bitki/toprak ürüne dahil değildir','Seçilen geometrik modelin ticari lisansı ve eklenen logonun kullanım hakkı doğrulanır.','Küçük saksılar, dekoratif değer ile günlük işlevi birleştirdiği için oyuncak dışı 3D baskı kataloğunda istikrarlı satış sağlar.',14,'Taban düzlüğü, duvar sürekliliği, drenaj deliği, su sızdırmazlık beklentisi ve yüzey çizikleri kontrol edilir.',false,true,14),
  (148,'3D-148','Lithophane · Kişiselleştirilmiş Fotoğraf Hediyesi','Işıklı ve duvar dekoru ürünleri',5,'A','Müşteri fotoğrafını ışık arkasından görünür hâle getiren kişiselleştirilmiş litofan panel; güçlü duygusal hediye.',240,600,390,1,'Beyaz PLA / PETG + opsiyonel LED taban','decor','Kişiselleştirilmiş Lithophane Fotoğraf Paneli, fotoğraftaki tonları farklı duvar kalınlıklarına çevirir; ışık açıldığında görüntü yüksek ayrıntıyla ortaya çıkar. Düz panel, kavisli çerçeve veya LED tabanlı masaüstü set olarak üretilebilir.','Standart panel yaklaşık 15 × 20 × 0,25 cm','65–120 g panel; çerçeve/LED hariç','FDM · dikey, yüzde 100 dolu değişken kalınlıklı litofan',0.12,100,4,0.4,'Destek gerekmez; uzun panelde geniş brim kullanılır.','Panel, çerçeve veya LED tabana geçirilir; ışık dağılımı ve yönü ayarlanır.','Klasik beyaz panel, sepya/renkli arka katman, siyah-beyaz çerçeve ve ahşap görünümlü taban','Dekoratif hediye; LED kullanılan sette yetişkin kurulumu önerilir.','Fotoğraf hediyesi, yıldönümü, aile portresi, evcil hayvan anısı, düğün ve kurumsal hatıra','Köşe korumalı kutu; LED ve adaptör varsa ayrı güvenli bölüm','Müşteri fotoğrafın kullanım hakkına sahip olmalıdır; üçüncü kişi ve telifli görseller yazılı onay olmadan üretilmez.','Kişiselleştirilmiş fotoğraf hediyeleri, ürünün ışık açıldığında dönüşmesi sayesinde yüksek algılanan değer ve güçlü duygusal bağ kuruyor.',15,'Fotoğraf ön izlemesi onaylanır; yüz ayrıntısı, minimum/maksimum kalınlık, ışık homojenliği ve çerçeve geçmesi test edilir.',false,true,15),
  (33,'3D-033','Kapibara','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','İnternet kültüründe güçlü görünürlüğe sahip sevimli kapibara; flexi, mini figür ve anahtarlık serilerine uygun.',90,180,115,10,'PLA','flexi','Kapibara, sade silueti ve sakin karakter algısıyla sosyal medyada yüksek tanınırlığa sahip bir figürdür. Standart ürün flexi/mini masaüstü formatında sunulur; meyve, şapka, içecek ve anahtarlık aksesuarlarıyla koleksiyon serisine dönüştürülebilir.','Yaklaşık 8,5 × 4,2 × 4,5 cm','30–55 g','FDM · tek parça veya print-in-place varyant',0.16,12,3,0.4,'Modele göre gerekmez; aksesuar varyantında sınırlı destek olabilir.','Ana gövde montajsız; seçilen aksesuar ayrıca takılabilir.','Kahve tonları, pastel, meyve teması, iki renk ve karışık koleksiyon','8+; aksesuar ve mini varyantlar küçük parça içerebilir.','Masaüstü figür, fidget, anahtarlık, hediye, sosyal medya kampanyası ve koleksiyon','Tekli kutu/poşet; karakter adı ve seri numarası etiketi opsiyonel','Kullanılan kapibara tasarımının ticari lisansı doğrulanır.','Etsy’de eklemli ve mini kapibara ürünleri yüksek değerlendirme adetleriyle görünür durumda.',16,'Yüz okunabilirliği, ayak tabanı, aksesuar geçmesi ve eklem hareketi kontrol edilir.',false,true,16),
  (72,'3D-072','Mekanik klavye switch clicker','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','Gerçek mekanik klavye switch’i kullanan tıklamalı fidget; ses ve his seçenekleriyle tekrar satışa uygun.',30,75,95,20,'PLA + mekanik klavye switch’i','fidget','Mekanik Switch Clicker, değiştirilebilir klavye switch’i sayesinde farklı ses ve basma hissi sunan kompakt bir fidget ürünüdür. Gövde rengi, switch türü ve anahtarlık bağlantısıyla çok sayıda SKU üretilebilir; küçük ölçüsü yüksek adetli baskıya uygundur.','Yaklaşık 4,5 × 2,8 × 1,8 cm','15–25 g + switch','FDM gövde + hazır mekanik switch',0.16,20,3,0.4,'Gerekmez.','Switch gövdeye preslenir; kapak ve anahtarlık aparatı takılır.','Gövde/kapak ayrı renk; lineer, tactile veya clicky switch seçenekleri','12+; sökülebilir switch ve küçük parçalar içerir.','Fidget, anahtarlık, oyuncu/klavye teması, promosyon ve kasa önü ürünü','Tekli kartela veya poşet; switch türü ve ses sınıfı etiketi','Gövde modelinin ticari lisansı ve kullanılan switch markasının sunum koşulları doğrulanır.','Print-in-place clicker ve mekanik switch fidget modelleri MakerWorld’ün hızlı baskı/trend listelerinde sık görünür.',17,'Her switch 20 basım testinden geçirilir; gövde geçmesi ve kapak tutuşu kontrol edilir.',false,true,17),
  (13,'3D-013','Axolotl','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Yumuşak hatlı, tek parça hareketli axolotl; pastel renkler ve sevimli masaüstü serileri için güçlü ürün.',90,210,120,10,'PLA','flexi','Flexi Axolotl, kıvrılabilen gövdesi ve belirgin solungaç formuyla hem duyusal fidget hem sevimli koleksiyon ürünü olarak çalışır. Tek parça basıldığı için montajsızdır; mini, standart ve anahtarlık varyantlarına ölçeklenebilir.','Yaklaşık 15 × 4,5 × 3 cm','35–60 g','FDM · print-in-place eklemli',0.2,12,3,0.4,'Gerekmez.','Montaj yok; solungaç uçları ve gövde eklemleri kontrol edilir.','Pastel pembe, beyaz, turkuaz, neon, çift renk ve karışık paket','8+; solungaç uçları ve küçük detaylar nedeniyle gözetim önerilir.','Fidget, masaüstü dostu, hediye, parti ürünü ve koleksiyon','Tekli şeffaf poşet veya kutu; karakter kartı opsiyonel','Seçilen modelin ticari kullanım izni doğrulanır.','Axolotl, MakerWorld ve pazar yerlerinde çok sayıda flexi varyantla kalıcı sevimli hayvan trendi oluşturuyor.',18,'İnce solungaçlar, burun yüzeyi, ilk katman ve tüm gövde eklemleri kontrol edilir.',false,true,18),
  (6,'3D-006','Mini ejderha anahtarlık','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Cep boy eklemli ejderha anahtarlığı; kasa önü, etkinlik dağıtımı ve çoklu renk paketleri için hızlı üretim.',35,65,42,20,'PLA / Silk PLA','custom','Mini Ejderha Anahtarlık, büyük flexi ejderhanın hareketli karakterini düşük malzeme ve kısa baskı süresiyle taşınabilir ürüne çevirir. Toplu promosyon, parti hediyesi ve mağaza kasa önü satışında yüksek adet potansiyeline sahiptir.','Yaklaşık 6,5 × 2,8 × 1,6 cm','10–18 g + halka','FDM · print-in-place mini eklemli',0.16,15,3,0.4,'Gerekmez.','Anahtarlık halkası elle takılır; eklemler ve bağlantı gözü kontrol edilir.','Tek renk, karışık renk paketleri, ipek ve kurumsal renkler','8+; küçük parça ve metal halka içerir.','Anahtarlık, çanta süsü, etkinlik dağıtımı, parti hediyesi ve promosyon','Tekli kilitli poşet veya kartela; barkod ve marka etiketi opsiyonel','Ticari üretim hakkı bulunan model kullanılmalıdır.','Mini flexi anahtarlıklar düşük fiyat, taşınabilirlik ve hediye formatıyla pazar yerlerinde sürekli talep görüyor.',19,'Halka gözü çekme testi, küçük eklem hareketi ve keskin çapak kontrolü yapılır.',false,true,19),
  (2,'3D-002','Bebek ejderha + açılır yumurta','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Açılır yumurta içinde bebek ejderha; sürpriz paket, hediye ve koleksiyon ürünü olarak yüksek sunum değeri.',300,600,260,3,'PLA / Silk PLA','flexi','Bebek Ejderha + Açılır Yumurta, ürünün kendisini ambalaj deneyimine dönüştüren iki parçalı bir settir. Yumurtanın içinden çıkan eklemli mini ejderha özellikle çocuk etkinliği, hediye paketi ve sürpriz ürün serilerinde güçlü bir anlatım sağlar.','Kapalı yumurta yaklaşık 11 × 8,5 × 8,5 cm','90–160 g / set','FDM · yumurta ve eklemli figür ayrı baskı',0.2,12,3,0.4,'Modele göre gerekmez veya yumurta kilidinde çok sınırlı destek kullanılır.','Figür montajsızdır; yumurta parçaları kapanma ve geçme testinden geçirilir.','Yumurta ve ejderha ayrı renk; pastel, ipek, gökkuşağı ve tema setleri','8+; küçük parçalar nedeniyle 3 yaş altına uygun değildir.','Sürpriz kutu, doğum günü, koleksiyon, hediye ve mağaza vitrin ürünü','Yumurta kendi kabı olarak kullanılır; mühür etiketi ve dış kutu opsiyonel','Seçilen ejderha ve yumurta modelinin ticari lisansı ayrı ayrı doğrulanır.','Ejderha + yumurta kombinasyonu, flexi ürünün viral gücünü sürpriz paket formatıyla birleştiriyor.',20,'Yumurta kapanma toleransı, menteşe/geçme yüzeyi ve figür eklemleri numunede kontrol edilir.',false,true,20),
  (7,'3D-007','Flexi Rex / T-Rex','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Tek parça hareketli T‑Rex; dinozor ilgisiyle flexi oyuncak davranışını birleştiren kalıcı seri ürünü.',150,300,165,5,'PLA','flexi','Flexi Rex, birbirine bağlı omur ve kuyruk parçalarıyla elde kıvrılan eklemli bir dinozor modelidir. Dinozor temasının zamansız talebi sayesinde sezon bağımsız çalışır; çocuk mağazası, müze mağazası ve masaüstü koleksiyonunda konumlanabilir.','Yaklaşık 14 × 4,5 × 5 cm','45–75 g','FDM · print-in-place eklemli',0.2,15,3,0.4,'Gerekmez.','Montaj yok; çene, kuyruk ve gövde eklemleri baskı sonrası açılır.','Doğal tonlar, neon, fosforlu görünüm, iki renk ve karışık seri','8+; ince kuyruk ve küçük detaylar içerir.','Oyuncak, müze/tema mağazası, masaüstü koleksiyon, hediye ve etkinlik','Şeffaf poşet veya koruyucu kutu; dinozor bilgi kartı opsiyonel','Üretilecek T‑Rex modelinin ticari lisansı doğrulanır.','Flexi dinozorlar, ejderha dışındaki en dayanıklı eklemli oyuncak temalarından biri.',21,'Ayak tabanı, çene boşluğu, kuyruk eklemleri ve denge numunede test edilir.',false,true,21),
  (73,'3D-073','2/4/6 tuşlu clicker küp','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','2, 4 veya 6 mekanik switch’li küp; farklı ses kombinasyonları ve premium paketlemeye uygun.',60,150,145,10,'PLA + 2/4/6 mekanik klavye switch’i','fidget','Çok Tuşlu Clicker Küp, bir gövdede farklı mekanik switch hislerini birleştirir. İki, dört ve altı tuşlu varyantlarla fiyat kademesi kurulabilir; switch renkleri ve ses profilleri kişiselleştirilebilir.','6 tuşlu model yaklaşık 5 × 5 × 5 cm','45–70 g + switchler','FDM gövde + hazır mekanik switchler',0.2,20,3,0.4,'Modele göre gerekmez.','Switchler ve kapaklar elle takılır; her yüz ayrı test edilir.','Küp yüzleri, tuş kapakları ve switch türleri ayrı seçilebilir','12+; çoklu sökülebilir küçük parça içerir.','Duyusal fidget, oyuncu/klavye hediyesi, masaüstü ve premium promosyon','Kutu, switch bilgi kartı ve yedek kapak opsiyonu','Model lisansı ve markalı donanım sunumu sipariş öncesi doğrulanır.','Clicker ürünleri kısa üretim süresi, video dostu ses/hareket ve varyant üretme kolaylığıyla yüksek adet potansiyeli taşıyor.',22,'Her switch, kapak, duvar kalınlığı ve küp yüzey toleransı ayrı kontrol edilir.',false,true,22),
  (84,'3D-084','Flexi Grid','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','İnce, sessiz ve esnek kafes hareketli fidget; hızlı üretim ve çoklu paket satışına uygun.',30,70,68,20,'PLA','fidget','Flexi Grid, birbirine bağlı ince hücrelerin akışkan biçimde bükülmesiyle sessiz bir duyusal deneyim sunar. Düz formda kolay paketlenir, düşük gramajı sayesinde promosyon ve yüksek adetli setlerde verimli çalışır.','Yaklaşık 10 × 3,5 × 1,2 cm','15–25 g','FDM · print-in-place esnek kafes',0.16,15,3,0.4,'Gerekmez.','Montaj yok; tüm hücreler serbest hareket edecek şekilde açılır.','Tek renk, gökkuşağı, iki renk ve karışık sınıf/etkinlik paketleri','8+; ince kafes parçaları zorlanmamalıdır.','Sessiz fidget, okul, ofis, promosyon, parti paketi ve duyusal set','Düz kilitli poşet veya kartela; kullanım yönü etiketi opsiyonel','Kullanılacak Flexi Grid modelinin ticari lisansı doğrulanır.','Kısa baskı süresine sahip esnek grid modelleri hızlı fidget seçkilerinde düzenli olarak yer alıyor.',23,'Her hücre hareketi, katman ayrılması ve kenar çapakları kontrol edilir.',false,true,23),
  (206,'3D-206','Parti çantası mini fidget paketi','Sezonluk ve olay bazlı viral ürünler',5,'A','Beş parçalı mini fidget seti; doğum günü çantası, sınıf etkinliği ve ekonomik toplu dağıtım için hazır paket.',120,240,185,10,'PLA','collection','Parti Çantası Mini Fidget Paketi, farklı dokunsal hareketler sunan beş küçük ürünü tek ekonomik sette birleştirir. İçerik yaş grubuna ve temaya göre flexi hayvan, grid, mini clicker gövdesi veya döner ürünlerle düzenlenebilir.','Sette 5 ürün; her biri yaklaşık 3–5,5 cm','35–70 g / set','FDM · çoklu tabla yerleşimi',0.2,15,3,0.4,'Set içeriğine göre desteksiz modeller seçilir.','Çoğu parça montajsız; varsa halka/clicker aparatı ayrıca takılır.','Karışık renk, tema rengi, kız/erkek ayrımı olmadan nötr set ve kurumsal renk','8+; mini parçalar nedeniyle 3 yaş altına uygun değildir.','Doğum günü çantası, sınıf ödülü, etkinlik, promosyon ve ekonomik hediye seti','Beşli kilitli poşet, tema etiketi ve isim etiketi opsiyonel','Setteki her modelin ticari üretim lisansı ayrı ayrı doğrulanır.','Mini eklemli hayvan ve fidget çoklu paketleri pazar yerlerinde parti çantası formatında yaygın.',24,'Set içeriği sayımı, her parçanın hareket testi, yaş uyarısı ve paket eşleştirmesi yapılır.',false,true,24),
  (15,'3D-015','Articulated Slug','Eklemli hayvanlar, flexi oyuncaklar ve masaüstü dostları',5,'A','Dalga gibi hareket eden uzun eklem dizili sevimli slug; düşük parça riski ve renk geçişinde güçlü görünüm.',90,210,120,10,'PLA / Silk PLA','flexi','Articulated Slug, gövde boyunca devam eden geniş eklemleri sayesinde elde akışkan biçimde kıvrılan tek parça bir flexi oyuncaktır. Sivri uç içermeyen yumuşak silueti, çocuk ve yetişkin fidget müşterisine aynı anda hitap eder.','Yaklaşık 16 × 5 × 3,5 cm','35–60 g','FDM · print-in-place eklemli',0.2,12,3,0.4,'Gerekmez.','Montaj yok; gövde eklemleri tabla sonrası kontrollü biçimde açılır.','Gökkuşağı, ipek, çift renk, pastel, neon ve karışık paket','8+; mini varyantlar 3 yaş altına uygun değildir.','Fidget, oyuncak, masaüstü, parti ürünü, hediye ve renk demo modeli','Tekli şeffaf poşet veya kutu; karakter kartı opsiyonel','Kullanılacak slug modelinin ticari üretim lisansı doğrulanır.','Eklemli slug, geniş ve tatmin edici gövde hareketiyle flexi kategorisinin uzun ömürlü klasiklerinden biridir.',25,'Tüm gövde eklemleri, göz/sap detayları, taban izi ve katman dayanımı kontrol edilir.',false,true,25),
  (68,'3D-068','Gear Cube','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','Her yüzü çevrildiğinde bağlı dişlileri birlikte hareket eden kompakt mekanik küp; premium masaüstü fidget.',120,300,170,5,'PLA gövde + PETG pim/dişli opsiyonu','fidget','Gear Cube, bir yüzün dönüşünü komşu dişlilere aktaran bağlantılı mekanizmasıyla klasik küp formuna sürekli hareket ekler. İki ve üç renkli üretim, açık dişli görünümü ve mekanik sesi sayesinde koleksiyon ve STEM hediyesi olarak konumlanır.','Yaklaşık 6 × 6 × 6 cm','80–125 g','FDM · çok parçalı dişli ve aks mekanizması',0.16,20,4,0.4,'Gerekmez; dişliler düz basılır.','Akslar, merkezler ve dişli yüzleri sıra ile monte edilip boşluk ayarı yapılır.','Kontrast iki/üç renk, tek renk teknik görünüm, neon ve kurumsal renk','14+; döner dişlilerde sıkışma aralığı ve küçük aks parçaları vardır.','Masaüstü fidget, STEM gösterimi, mekanik hediye, koleksiyon ve premium promosyon','Koruyucu kutu; temel hareket şeması ve bakım kartı opsiyonel','Seçilen Gear Cube mekanizmasının ticari lisansı doğrulanır.','Dişli fidgetler klasik küp davranışını görünür mekanikle birleştirdiği için uzun ömürlü ve yeniden izlenebilir bir ürün ailesidir.',26,'Her yüz 50 tam tur, dişli kavrama, aks tutuşu, sıkışma ve aşırı boşluk açısından test edilir.',false,true,26),
  (67,'3D-067','Gyroscopic Rings / Gyro Halkaları','Fidget, clicker, mekanik ve duyusal ürünler',5,'A','İç içe halkaları bağımsız eksenlerde dönen print-in-place gyro; sessiz ve görsel olarak güçlü masaüstü fidget.',45,120,72,10,'PLA','fidget','Gyroscopic Rings, aynı merkezde birbirine bağlı halkaların farklı eksenlerde serbestçe dönmesiyle küresel bir hareket oluşturur. Tek parça basılabilen doğru toleranslı varyant, montaj gerektirmeden hızlı üretim ve yüksek adet avantajı sağlar.','Yaklaşık Ø 7 cm','20–35 g','FDM · print-in-place iç içe halkalar',0.16,15,3,0.4,'Gerekmez; köprüleme ve soğutma ayarı önemlidir.','Montaj yok; halkalar tabla sonrası sırayla serbest bırakılır.','Tek renk, gökkuşağı, ipek, neon ve karışık toptan paket','8+; halkalar zorlanmamalı ve küçük çocuklarda gözetim gerekir.','Sessiz fidget, masaüstü, okul, promosyon, geometri/STEM gösterimi ve hediye','Tekli poşet veya kartela; dönüş eksenlerini gösteren piktogram opsiyonel','Kullanılacak gyro modelinin ticari lisansı doğrulanır.','Gyro halkaları, tek parçada karmaşık hareket göstermesi ve düşük gramajı sayesinde fidget seçkilerinde kalıcı bir mekanik klasik.',27,'Tüm halkalar 30 dönüş, tolerans, katman yapışması ve kırık köprü açısından kontrol edilir.',false,true,27),
  (91,'3D-091','Impossible Passthrough Illusion','Fidget, clicker, mekanik ve duyusal ürünler',4,'A','Bir parçanın imkânsız görünümle diğerinin içinden geçtiği optik/mekanik masaüstü illüzyonu.',90,180,115,10,'PLA / PETG','fidget','Impossible Passthrough, iki geometrik parçanın hassas açı ve boşluk hesabı sayesinde birbirinin içinden geçiyormuş gibi görünmesini sağlayan mekanik bir illüzyondur. Kamera önünde şaşırtıcı sonuç verir; masaüstü bulmaca ve konuşma başlatıcı ürün olarak çalışır.','Yaklaşık 8 × 8 × 8 cm','40–75 g','FDM · iki parçalı hassas geçiş geometrisi',0.16,15,3,0.4,'Gerekmez.','Montaj yok; iki parça eşleştirilir ve doğru geçiş yönü gösterilir.','Yüksek kontrast iki renk, tek renk, pastel, neon ve kurumsal set','8+; bulmaca/fidget ürünü.','Masaüstü illüzyon, fidget, STEM gösterimi, hediye, etkinlik ve video','İki parçalı kutu veya kartela; çözümü ele vermeyen başlangıç piktogramı opsiyonel','Seçilen passthrough geometrisinin ticari kullanım lisansı doğrulanır.','İmkânsız görünen tek hareket, izleyicide tekrar izleme ve deneme isteği uyandırdığı için kısa video formatında güçlüdür.',28,'Geçiş 20 çevrim, yüzey pürüzü, açı toleransı ve parça deformasyonu açısından test edilir.',false,true,28),
  (158,'3D-158','HueForge Art Panel','Işıklı ve duvar dekoru ürünleri',5,'A','Filament değişimleriyle çok tonlu kabartmalı görsel oluşturan ince HueForge sanat paneli; fotoğraf ve kurumsal tasarıma uygun.',180,420,310,2,'Çok renk PLA','decor','HueForge Art Panel, farklı renk filamentlerin belirli katmanlarda değiştirilmesiyle ışık geçirgenliğini ve kabartmayı kullanarak çok tonlu bir görüntü oluşturur. Fotoğraf, illüstrasyon, logo veya özgün sanat; çerçeveli masaüstü ve duvar dekoruna dönüştürülebilir.','Standart yaklaşık 20 × 20 × 0,2 cm','80–160 g; çerçeve hariç','FDM · katman bazlı filament değişimli kabartmalı panel',0.08,100,2,0.4,'Gerekmez.','Panel baskı sonrası temizlenir; opsiyonel çerçeveye veya standa geçirilir.','Fotoğrafa göre 3–6 renk, monokrom, sepya, marka renkleri ve özel palet','Dekoratif ürün; oyuncak değildir.','Duvar sanatı, portre, evcil hayvan resmi, logo, etkinlik hediyesi ve koleksiyon','Yüzey koruyucu kâğıt, köşe koruması ve düz kutu; çerçeve ayrı sabitlenir','Müşteri görselin kullanım hakkına sahip olmalıdır; korunan karakter ve sanat eserleri izin olmadan üretilmez.','HueForge kategorisi, kişiselleştirilmiş fotoğraf ve çok renkli filament sanatını düz, kolay paketlenen premium üründe birleştiriyor.',29,'Renk değişim katmanları, ton geçişi, nozzle izleri, panel düzlüğü ve çerçeve geçmesi kontrol edilir.',false,true,29),
  (164,'3D-164','Blind-Box Mini Animal Series','Koleksiyon, masa oyunu ve eğitim ürünleri',5,'A','Kapalı paketten sürpriz çıkan numaralı mini hayvan koleksiyonu; seri tamamlama ve tekrar sipariş odaklı.',60,180,95,20,'PLA','collection','Blind-Box Mini Animal Series, aynı görsel dilde tasarlanmış farklı mini hayvanları kapalı ve numaralı paketlerle sunar. Standart, nadir renk ve özel aksesuar katmanları kurulabilir; toptan kutular karakter dağılımı kontrollü hazırlanır.','Figür yaklaşık 4,5–6 cm; kapsül/kutu modele göre','20–45 g / paket','FDM · mini figür + kapalı kapsül/kutu',0.16,15,3,0.4,'Desteksiz mini figürler seçilir; aksesuar varyantı modele göre değişir.','Çoğu figür montajsızdır; aksesuar, seri kartı ve kapsül paketlemede birleştirilir.','Pastel seri, neon seri, doğal ton, nadir ipek renk ve kurumsal koleksiyon','8+; mini figür ve aksesuarlar küçük parça içerir.','Kör kutu, koleksiyon, kasa önü, etkinlik, parti hediyesi ve marka maskotu','Mühürlü kapsül veya numaralı opak kutu; seri kontrol listesi ve nadirlik bilgisi','Tüm karakterler özgün veya ticari lisanslı olmalıdır; korunan karakterler kullanılmaz.','Kör kutu formatı, mini hayvanların koleksiyon davranışını ve renk varyantlarını tekrar sipariş döngüsüne dönüştürür.',30,'Karakter dağılımı, paket içeriği, nadirlik oranı, küçük parça uyarısı ve mühür bütünlüğü kontrol edilir.',false,true,30)
on conflict (sku) do update set
  name = excluded.name,
  group_name = excluded.group_name,
  viral_strength = excluded.viral_strength,
  machine_fit = excluded.machine_fit,
  details = excluded.details,
  production_minutes_min = excluded.production_minutes_min,
  production_minutes_max = excluded.production_minutes_max,
  base_unit_price = excluded.base_unit_price,
  min_order_quantity = excluded.min_order_quantity,
  material = excluded.material,
  image_key = excluded.image_key,
  description = excluded.description,
  standard_dimensions = excluded.standard_dimensions,
  approximate_weight = excluded.approximate_weight,
  print_method = excluded.print_method,
  layer_height_mm = excluded.layer_height_mm,
  infill_percent = excluded.infill_percent,
  wall_count = excluded.wall_count,
  nozzle_mm = excluded.nozzle_mm,
  supports = excluded.supports,
  assembly = excluded.assembly,
  color_options = excluded.color_options,
  age_recommendation = excluded.age_recommendation,
  usage_areas = excluded.usage_areas,
  packaging = excluded.packaging,
  license_note = excluded.license_note,
  market_signal = excluded.market_signal,
  popularity_rank = excluded.popularity_rank,
  quality_note = excluded.quality_note,
  is_featured = excluded.is_featured,
  is_published = excluded.is_published,
  sort_order = excluded.sort_order,
  updated_at = now();

select setval(
  pg_get_serial_sequence('public.print_products', 'id'),
  greatest((select max(id) from public.print_products), 1),
  true
);

commit;

select
  count(*) as total_products,
  count(*) filter (where is_published) as active_products,
  count(*) filter (where not is_published) as research_products,
  count(*) filter (where is_featured) as featured_products,
  min(popularity_rank) filter (where is_published) as first_rank,
  max(popularity_rank) filter (where is_published) as last_rank
from public.print_products;

select popularity_rank, sku, name
from public.print_products
where is_published
order by popularity_rank;
